import type { ProjectEntry } from '../data/projects.ts';
import { prefersReducedMotion } from './motion.ts';

/** MIME type for a project video, from its extension. */
export function videoType(src: string): string {
    return src.split('.').pop()?.toLowerCase() === 'webm' ? 'video/webm' : 'video/mp4';
}

/** Poster next to the video: demo.mp4 -> demo.poster.webp (generated by `npm run media:posters`). */
export function videoPoster(src: string): string {
    return src.replace(/\.[^./]+$/, '.poster.webp');
}

/** Widths of the card-sized copies of a project's image (generated by `npm run media:thumbs`). */
export const THUMB_WIDTHS = [320, 640] as const;

/** A card-sized copy of an image, next to it: demo.webp -> demo.640.webp. */
export function thumbOf(src: string, width: (typeof THUMB_WIDTHS)[number]): string {
    return src.replace(/\.[^./]+$/, `.${width}.webp`);
}

/** The image that stands for a project, when it is not a video: the image, or a gallery's first picture. */
export const stillImage = (p: ProjectEntry): string | null =>
    p.media.type === 'video' ? null : p.media.type === 'image' ? p.media.src : p.media.images[0].src;

/** The still a card shows for a project before anything plays: a video's poster, or a card-sized copy of its image. */
export const still = (p: ProjectEntry): string => {
    const image = stillImage(p);
    return image ? thumbOf(image, 640) : videoPoster((p.media as { src: string }).src);
};

/** Narrowest a project's own image is (README, Media): offered to cards that can grow wider than the copies. */
const IMAGE_MIN_WIDTH = 1024;

/**
 * `src`, `srcset` and `sizes` of a card's still: the browser picks the smallest copy that is sharp at the size the
 * card shows it (`sizes`, a CSS width or media list). `full` also offers the image itself, for cards that can span a
 * tablet's width. Posters come in one size, already small.
 */
export function stillAttrs(p: ProjectEntry, sizes: string, full = false): string {
    const image = stillImage(p);
    if (!image) return `src="${still(p)}"`;
    const set = THUMB_WIDTHS.map((w) => `${thumbOf(image, w)} ${w}w`);
    if (full) set.push(`${image} ${IMAGE_MIN_WIDTH}w`);
    return `src="${thumbOf(image, 640)}" srcset="${set.join(', ')}" sizes="${sizes}"`;
}

let observer: IntersectionObserver | undefined;
const onScreen = new Set<HTMLVideoElement>();
let tabListening = false;

/**
 * Play the videos under `root` only while they are on (or near) screen and the tab is shown, and pause them otherwise.
 * Videos are rendered with preload="none", so nothing downloads until a video first comes into view.
 * With reduced motion, videos never autoplay and keep showing their poster.
 */
export function playVideosWhenVisible(root: ParentNode): void {
    observer?.disconnect();
    onScreen.clear();
    if (prefersReducedMotion()) return;
    if (!tabListening) {
        tabListening = true;
        document.addEventListener('visibilitychange', () => {
            for (const video of onScreen)
                if (document.hidden) video.pause();
                else video.play().catch(() => {});
        });
    }

    observer = new IntersectionObserver(
        (entries) => {
            for (const entry of entries) {
                const video = entry.target as HTMLVideoElement;
                if (entry.isIntersecting) {
                    onScreen.add(video);
                    if (!document.hidden) video.play().catch(() => {}); // autoplay can be refused (e.g. data saver); the poster stays
                } else {
                    onScreen.delete(video);
                    video.pause();
                }
            }
        },
        { rootMargin: '200px 0px' }
    );
    root.querySelectorAll('video').forEach((video) => observer?.observe(video));
}
